{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket is not configured with versioning, which can lead to data loss in case of accidental deletion or overwrite."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access block configured, which can expose the bucket to unauthorized access."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have access logging enabled, which can make it difficult to track and monitor access to the bucket."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.admin_dashboard",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket is not configured with default KMS encryption, which can leave the data stored in the bucket unencrypted."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "admin_dashboard" {
  bucket = "smart-city-parking-management-system-s3-admin-dashboard-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket_versioning" "admin_dashboard_versioning" {
  bucket = aws_s3_bucket.admin_dashboard.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "admin_dashboard_public_access_block" {
  bucket = aws_s3_bucket.admin_dashboard.id
  block_public_acls   = true
  block_public_policy = true
  ignore_public_acls  = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "admin_dashboard_logging" {
  bucket = aws_s3_bucket.admin_dashboard.id
  target_bucket = aws_s3_bucket.admin_dashboard.id
  target_prefix = "/logs/"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "admin_dashboard_encryption" {
  bucket = aws_s3_bucket.admin_dashboard.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_encryption_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_kms_key" "s3_encryption_key" {
  description             = "KMS key for S3 encryption"
  enable_key_rotation = true
}",
  "fix_summary": "Enabled versioning, public access block, access logging, and default KMS encryption for the S3 bucket."
}
